from owner import snapshot,update
func verify(row,n){assert_equal(row["new-array"],[n]) assert_equal(row["new-dict"],{"v":n}) mut k:=0 while k<8 { assert_equal(row[k],0) k+=1 } assert_equal(len(row),10)}
